#nullable enable

using Alba;
using Spend.Contracts;
using Spend.Views;
using Shouldly;
using Xunit;

namespace Spend.IntegrationTests.Slices.Spend;

/// <summary>
/// Generated from the model's GT cells. Pattern: state-view. Status: ready.
///
/// GT, not GWT: a read model only ever reads events that already exist, so there is no command to be the
/// WHEN. Append the GIVEN, assert the view.
///
/// **NO WaitForNonStaleProjectionDataAsync, and that is deliberate rather than an omission.** The generated
/// hint says to wait, because codegen registers a multi-stream view Async by default — following Marten's
/// own guidance. This folder overrides that to `Inline` in ViewRegistrations, for a stated reason: it exists
/// to test whether a projection can guard a cross-aggregate invariant, and Inline is the STRONGEST form of
/// that claim. Inline updates inside the append's own transaction, so the view is current the moment
/// `Given` returns and a wait would assert nothing. If that registration is ever moved back to Async, these
/// four tests are where it will show up — as intermittent failures that look exactly like a broken projection.
/// </summary>
public sealed class DepartmentSpendTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static readonly Guid Department = SeedData.DepartmentId;
    private static readonly Guid Project = SeedData.ProjectId;

    /// <summary>Through the READ ENDPOINT, not the document store: that covers the projection and the query
    /// surface together, which is what a caller actually gets.</summary>
    private async Task<DepartmentSpend> TheDepartment()
    {
        var result = await Host.Scenario(_ =>
        {
            _.Get.Url($"/departments/{Department}/spend");
            _.StatusCodeShouldBeOk();
        });
        return result.ReadAsJson<DepartmentSpend>()!;
    }

    // A department with a budget and no projects has all of it available
    //   GIVEN Department Budget Set(budget=100000)
    //   THEN  DepartmentSpend(budget=100000, committed=0, available=100000)
    [Fact]
    public async Task ADepartmentWithABudgetAndNoProjectsHasAllOfIt()
    {
        await Given(Department, new DepartmentBudgetSet(Department, 100_000m));

        var row = await TheDepartment();
        row.Budget.ShouldBe(100_000m);
        row.Committed.ShouldBe(0m);
        row.Available.ShouldBe(100_000m);

        // A brand-new parent has an EMPTY group, not a null one. The repeated-group form has to survive a
        // row with no lines at all — which is one of the two things a second read model could never do.
        row.Projects.ShouldBeEmpty();
    }

    // Committed spend in ANY project reduces the department's available budget
    //   GIVEN Spend Committed(amount=40000)
    //   THEN  DepartmentSpend(budget=100000, committed=40000, available=60000)
    [Fact]
    public async Task CommittedSpendInANYProjectReducesTheDepartmentSAvailableBudget()
    {
        await Given(Department, new DepartmentBudgetSet(Department, 100_000m));
        await Given(Project,
            new ProjectOpened(Project, Department, "Rewire the hall"),
            new SpendCommitted(Project, Department, 40_000m));

        // "ANY project" is the point: the commitment is in a PROJECT stream and the total is on the
        // DEPARTMENT row, which is what makes this view multi-stream at all.
        var row = await TheDepartment();
        row.Budget.ShouldBe(100_000m);
        row.Committed.ShouldBe(40_000m);
        row.Available.ShouldBe(60_000m);
    }

    // A release puts the money back
    //   GIVEN Commitment Released(amount=40000)
    //   THEN  DepartmentSpend(budget=100000, committed=0, available=100000)
    [Fact]
    public async Task AReleasePutsTheMoneyBack()
    {
        await Given(Department, new DepartmentBudgetSet(Department, 100_000m));
        await Given(Project,
            new ProjectOpened(Project, Department, "Rewire the hall"),
            new SpendCommitted(Project, Department, 40_000m),
            new CommitmentReleased(Project, Department, 40_000m));

        var row = await TheDepartment();
        row.Committed.ShouldBe(0m);
        row.Available.ShouldBe(100_000m);

        // The LINE goes back to zero too, not just the header. A fold that applied the release only to the
        // department total would pass every other assertion in this file.
        row.Projects.ShouldHaveSingleItem().ProjectCommitted.ShouldBe(0m);
    }

    // The row carries one line per project
    //   GIVEN Project Opened(name=Rewire the hall)
    //   THEN  DepartmentSpend(name=Rewire the hall, projectCommitted=0)
    [Fact]
    public async Task TheRowCarriesOneLinePerProject()
    {
        await Given(Department, new DepartmentBudgetSet(Department, 100_000m));
        await Given(Project, new ProjectOpened(Project, Department, "Rewire the hall"));

        var row = await TheDepartment();
        var line = row.Projects.ShouldHaveSingleItem();
        line.ProjectId.ShouldBe(Project);
        line.Name.ShouldBe("Rewire the hall");
        line.ProjectCommitted.ShouldBe(0m);

        // THE GT WORTH WRITING ABOVE ALL OTHERS: what the view IGNORES. Opening a project must not move
        // the department's committed total — which the drawing already claims, and which is the one thing a
        // projection can get wrong that no other test here would notice.
        row.Committed.ShouldBe(0m);
        row.Available.ShouldBe(100_000m);
    }
}
